import{_ as e,o as t,c as i,a2 as o}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Combat overview","description":"","frontmatter":{},"headers":[],"relativePath":"guide/combat/overview.md","filePath":"guide/combat/overview.md"}'),n={name:"guide/combat/overview.md"};function s(r,a,d,l,c,m){return t(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="combat-overview" tabindex="-1">Combat overview <a class="header-anchor" href="#combat-overview" aria-label="Permalink to &quot;Combat overview&quot;">​</a></h1><ul><li><strong>Design status:</strong> Accepted foundations; Experimental localized combat; Proposed advanced mechanics.</li><li><strong>Implementation:</strong> Stage 2A natural melee and Anatomy assessment. Aiming and shield disability consequences are deferred.</li><li><strong>Availability:</strong> current availability is not verified here; the experiment is not a promise of generally available gameplay.</li><li><strong>Verification:</strong> automated tests and first client observation recorded; extended gameplay and balance validation incomplete.</li></ul><p><strong>Reviewed:</strong> 2026-10-08 against the <a href="/Syrolands-Public/game-design/combat/overview.html">specification</a>. Public projection reviewed 2026-10-09; no new playtest.</p><p><a href="/Syrolands-Public/game-design/combat/overview.html">Full design specification</a></p><h2 id="what-it-is-and-why-it-matters" tabindex="-1">What it is and why it matters <a class="header-anchor" href="#what-it-is-and-why-it-matters" aria-label="Permalink to &quot;What it is and why it matters&quot;">​</a></h2><p>Syrolands keeps ordinary attacks automatic while exploring how injuries to different body regions can make combat decisions more meaningful. You should not need to click for every swing. Optional advanced interaction is intended to reward judgment alongside character skills.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>Ordinary combat reduces global health. The localized experiment also tracks integrity across seven body regions, with local trauma distinct from health damage. A first fixture focuses on human players; it does not establish complete creature support.</p><p>Aiming at a chosen region is intended to be an attempt, never a guaranteed hit or impact location. That interaction is deferred. Losing shield use through a disabled supporting arm is accepted design but also deferred; do not expect that consequence from Stage 2A.</p><h2 id="progression-and-specialization" tabindex="-1">Progression and specialization <a class="header-anchor" href="#progression-and-specialization" aria-label="Permalink to &quot;Progression and specialization&quot;">​</a></h2><p>The current experiment includes qualitative region assessment on a successful Anatomy use. A complete progression or specialization system is not established by this slice. Advanced combat and final balance remain future work, not promised unlocks.</p><h2 id="related-systems" tabindex="-1">Related systems <a class="header-anchor" href="#related-systems" aria-label="Permalink to &quot;Related systems&quot;">​</a></h2><p><a href="/Syrolands-Public/game-design/combat/body-regions.html">Body regions</a>, <a href="/Syrolands-Public/game-design/combat/damage.html">damage and trauma</a>, <a href="/Syrolands-Public/game-design/combat/targeting.html">targeting and assessment</a>, and <a href="/Syrolands-Public/game-design/combat/disability.html">shield disability</a> contain the detailed intent and limits. <a href="/Syrolands-Public/game-design/skills-and-knowledge.html">Skills and knowledge</a> provides broader design context.</p><p>No new playtest was performed for this guide. Automated checks and initial observation do not establish full gameplay or balance validation.</p><h2 id="explore-combat" tabindex="-1">Explore combat <a class="header-anchor" href="#explore-combat" aria-label="Permalink to &quot;Explore combat&quot;">​</a></h2><p><a href="/Syrolands-Public/guide/combat/limbs-and-trauma.html">Limbs and Trauma</a> · <a href="/Syrolands-Public/guide/combat/weapons-and-damage.html">Weapons and Damage Types</a> · <a href="/Syrolands-Public/guide/combat/armor-and-protection.html">Armor and Protection</a> · <a href="/Syrolands-Public/guide/combat/targeting-and-anatomy.html">Targeted Attacks and Anatomy</a> · <a href="/Syrolands-Public/guide/combat/stamina-and-reactive-combat.html">Stamina and Reactive Combat</a>.</p><p><a href="/Syrolands-Public/game-design/combat/status-and-open-questions.html">Combat status and open questions</a> records what is accepted, implemented or still proposed. A manually triggered attack is under consideration; making it mandatory would conflict with the automatic baseline, and that decision remains open.</p>',17)])])}const g=e(n,[["render",s]]);export{u as __pageData,g as default};
